// convert the source into THEORY[lang] (sections with block lists) for the renderer in app.js
(function () {
  const pick = (t, i) => (Array.isArray(t) ? t[i] : t);
  const out = {};
  ['en', 'gu', 'hi'].forEach((L, i) => {
    out[L] = TH_SRC.map((s) => ({ id: s.id, svg: s.svg, h: pick(s.h, i), blocks: s.b.map(([k, v]) => {
      if (k === 'li') return [k, v.map((x) => pick(x, i))];
      if (k === 'tbl') return [k, [v[0][i], v[1].map((row) => row.map((c) => pick(c, i)))]];
      if (k === 'go') return [k, [v[0], pick(v[1], i)]];
      return [k, pick(v, i)];
    }) }));
  });
  window.THEORY_BLOCKS = out;
})();
